X0X_COLD void ui_init(void)
{
#if BOARD_SMK37
    smc_ui_cancel();
#endif
    int i;
    memset(&ui, 0, sizeof ui);
    memset(kbd_held_note, 0, sizeof kbd_held_note);
    memset(kbd_held_key, 0, sizeof kbd_held_key);
    memset(kbd_arp_n, 0, sizeof kbd_arp_n);
    memset(bass_rec_step, 0, sizeof bass_rec_step);
    memset(bass_rec_pat, 0, sizeof bass_rec_pat);
    memset(bass_rec_playing, 0, sizeof bass_rec_playing);
    undo_lanes = 0;
    ui.view = V_SEQ;                  /* start on the visible step grid; EDIT opens sound */
    ui.prev_view = V_PART;
    ui.part = PART_909;
    ui.held_step = -1;
    ui.brk_held = -1;
    ui.hold_step = -1;
    ui.chain_first = -1;
    ui.touched = -1;
    ui.overlay = O_NONE;
    ui.outline_ok = 0;
    ui.dirty = 0;
    ui.save_failed = 0;
    save_wait = 0;
    palette_set(proj.set.palette);
    for (i = 0; i < 4; i++)
        blit_hash[i] = 0;
    build_pages();
    undo_start();                                   /* the project as loaded is where undo stops */
    if (project_storage_unsupported()) {
        ui.save_failed = 1;
        say("NEWER DATA: LOAD BLOCKED", 0);
    }
}

/* A transaction borrows the undo baseline and holds the audio engine. Setting the hold before
 * the transport check closes the gap in which the audio ISR could consume a queued Start. */
X0X_COLD static int project_acquire(int reset)
{
    if (project_busy || perf_testing() || (!reset && (ui.rec || ui.keys || plat_keys() ||
        ui.held_step >= 0 || ui.hold_step >= 0 || ui.brk_held >= 0)))
        return UI_PROJECT_BUSY;
#if BOARD_SMK37
    {
        extern int smk_project_active(void), smc_project_active(void);
        if (!reset && (smk_project_active() || smc_project_active()))
            return UI_PROJECT_BUSY;
    }
#endif
    engine_project_hold(1);
    if (!reset && (seq.playing || seq.req_start || seq.req_cont || seq.req_stop || engine_project_notes())) {
        engine_project_hold(0);
        return UI_PROJECT_BUSY;
    }
    project_busy = 1;
    undo_commit_stable();                       /* no uncommitted gesture is lost when staging borrows shadow */
    return 0;
}

int ui_project_begin(void) { return project_acquire(0); }

X0X_COLD void ui_project_end(int apply)
{
    if (!project_busy)
        return;
    if (apply) {
        engine_project_flush();                     /* old note-offs use the channels that sent the notes */
#if BOARD_SMK37
        {
            extern void smk_project_reset(void), smc_project_reset(void);
            smk_project_reset();                    /* clip key notes depend on the old project's scale/chord */
            smc_project_reset();
        }
#endif
        project_commit_stage();
        engine_init(proj.pat, &proj.arr.song, proj.arr.lane, &proj.sound);
        seq.bpm = (float)proj.set.bpm_x10 / 10.0f;
        seq.ext_bpm = seq.bpm;
        seq.accent_q7 = proj.set.accent_q7;
        project_apply_io();
        seq.clk_src = PROJ_CLK_SRC(proj.set.bt);
#if BOARD_SMK37
        extern uint8_t smk_clip_mode_on(void);
        if (smk_clip_mode_on())
            seq.clk_src = SEQ_CLK_AUTO;
#endif
        engine_apply_sound(&proj.sound);
        engine_brk_loops();
        ui_init();
        mark_dirty();                               /* reset/import are saved only by the ordinary save policy */
        project_revision++;
    } else {
        memcpy(undo_shadow, (uint8_t *)&proj + UNDO_OFF, UNDO_BYTES);
    }
    project_input_sync();                            /* consume controls held or turned during the transaction */
    ui.act_t = plat_ms();
    project_busy = 0;
    engine_project_release();
}

X0X_COLD int ui_project_load(void)
{
    int rc = ui_project_begin();
    if (rc) {
        say("STOP PLAYING TO LOAD", 0);
        return rc;
    }
    rc = project_load_stage();
    ui_project_end(rc == 0);
    if (!rc)
        ui.dirty = 0;                                /* the last saved project is now the live project */
    say(rc ? "NO VALID SAVED PROJECT" : "SAVED PROJECT LOADED", 0);
    return rc;
}

X0X_COLD int ui_project_reset(void)
{
    int rc = project_acquire(1);
    if (rc) {
        say("PROJECT BUSY", 0);
        return rc;
    }
    project_reset_stage();
    ui_project_end(1);
    say("PROJECT RESET: SAMPLES KEPT", 0);
    return 0;
}

/* AUTOSAVE: changes are saved by themselves while the pattern is stopped and nothing has been touched
 * for AUTOSAVE_QUIET ms, at most every AUTOSAVE_GAP ms. Stopped only: a flash erase silences the
 * audio. Only the objects that changed are written (project.c), usually one or two sectors. */
#define AUTOSAVE_GAP 20000u
static void autosave(void)
{
    uint32_t now = plat_ms();
#if BOARD_SMK37
    extern uint8_t smk_ck_flash_busy(void), smk_clip_mode_on(void);
#endif
    if (project_busy || ui_boot_flash_busy())
        return;
    if (save_wait && !seq.playing && !seq.req_start && !seq.req_cont && !seq.req_stop && !ui.rec && !perf_save_busy()) {
#if BOARD_SMK37
        if (smk_clip_mode_on() && (smk_ck_flash_busy() || now - ui.act_t < AUTOSAVE_QUIET))
            return;                                    /* keep the queued SAVE until clip playing has gone quiet */
#endif
        save_project();
        return;
    }
#if BOARD_SMK37
    if (smk_ck_flash_busy())                          /* ui_frame runs before smk_ck_poll on display frames */
        return;
#endif
    if (!ui.dirty || (proj.set.autosave_off && !ui.last_autosave) || seq.playing || seq.req_start || seq.req_cont || seq.req_stop || ui.rec || perf_testing() ||
        ui.overlay == O_ASK || now - ui.act_t < AUTOSAVE_QUIET || (ui.saved_t && now - ui.saved_t < AUTOSAVE_GAP))
        return;
    ui.saved_t = now;
    ui.last_autosave = 0;
    switch (project_save()) {
    case 0:
        ui.dirty = 0;
        ui.save_failed = 0;
        say("AUTOSAVED", 0);
        break;
    case -9:
        ui.save_failed = 1;
        say("NEWER DATA: NOT SAVED", 0);
        break;
    case -7:
        ui.save_failed = 1;
        say("MEMORY FULL: NOT SAVED", 0);
        break;
    default:
        ui.save_failed = 1;
        say("SAVE FAILED", 0);
        break;
    }
}

void ui_frame(void)
{
    uint32_t i;
    input();
    if (project_busy) {
#if BOARD_SMK37
        smc_ui_cancel();
#endif
        draw_header();                             /* keep transfer status visible; samples and runtime stay untouched */
        return;
    }
#if BOARD_SMK37
    smc_frame();
#endif
    if (!project_busy) {   /* GLO > MIDI > CLOCK SOURCE; clip mode always uses AUTO */
        static uint8_t waited;
        uint8_t w;
#if BOARD_SMK37
        extern uint8_t smk_clip_mode_on(void);
        seq.clk_src = smk_clip_mode_on() ? SEQ_CLK_AUTO : PROJ_CLK_SRC(proj.set.bt);
#else
        seq.clk_src = PROJ_CLK_SRC(proj.set.bt);
#endif
        w = (uint8_t)seq_clock_waiting(&seq);
        if (w && !waited)
            say("WAITING FOR CLOCK", 0);
        waited = w;
    }
#if X0X_BASS_TAGGED_SOUND
    if(undo_wait) {
        int direction=undo_wait==2;
        if(undo.cur!=undo_wait_cur || undo.used!=undo_wait_used ||
           engine_bass_choice_serial()!=undo_wait_serial ||
           memcmp(undo.region,undo.shadow,undo.len))undo_wait=0;
        else do_undo(direction);
    }
#endif
    if(ui.overlay!=O_LIST || ui.help) peer_scroll.active=0;
    else { int visible=0;for(unsigned row=ui.list_top;row<ui.list_n && row<ui.list_top+6u;row++)
        if(list_rows[row].kind==R_BTNAME)visible=1;
        if(!visible)peer_scroll.active=0; }
    undo_tick();
    autosave();
    if (!project_busy)
        perf_test_tick();
    if (ui.view == V_PERF && !perf_testing())
        perf_window(0);
    for (i = 0; i < NPARTS; i++)
        eng_peak[i] = (uint16_t)(eng_peak[i] - (eng_peak[i] >> 3));
    for (i = 0; i < NKIT * NDRUM; i++) {              /* the drum tracks' hits fall as the part meters do */
        volatile uint8_t *h = &eng_hit[i / NDRUM][i % NDRUM];
        *h = (uint8_t)(*h - (*h >> 3) - (*h ? 1 : 0));
    }
#if BOARD_SMK37
    if (smc_ui_active())
        smc_ui_draw();
    else
#endif
    {
        draw_header();
        draw_main();
        draw_knobs();
    }
    leds();
    ui.frame++;
}

void ui_input_only(void) { input(); }
int ui_dirty(void) { return ui.dirty != 0; }
void ui_say(const char *a, const char *b) { say(a, b); }

/* SPDX-License-Identifier: GPL-3.0-only */
#include "adoption.h"
#include "core.h"
#include <string.h>

static int model_valid(unsigned model)
{
    return model == X0X_MBOOT_PRO || model == X0X_MBOOT_ELITE;
}

static int terminated_version(const uint8_t *version)
{
    for (unsigned i = 0; i < 32; ++i)
        if (!version[i]) return 1;
    return 0;
}

int x0x_mboot_same_head(unsigned model, const uint8_t *candidate, size_t size,
    const uint8_t *approved_head, size_t approved_size)
{
    return model_valid(model) && candidate && approved_head &&
        size == X0X_MBOOT_HEAD_SIZE && approved_size == size &&
        memcmp(candidate, approved_head, size) == 0;
}

int x0x_mboot_prepare(unsigned model,
    const uint8_t *image, size_t image_size,
    const uint8_t *approved_image, size_t approved_image_size,
    const uint8_t *container, size_t container_size,
    const uint8_t *approved_container, size_t approved_container_size,
    uint8_t *output, size_t output_size)
{
    uint8_t head[X0X_MBOOT_HEAD_SIZE];
    struct core_config config;
    struct core_record record;
    unsigned configurations = 0;
    if (!model_valid(model) || !image || !approved_image || !container ||
        !approved_container || !output || image_size != X0X_MBOOT_FLASH_SIZE ||
        approved_image_size != image_size || output_size != image_size)
        return X0X_MBOOT_ARGUMENT;
    if (memcmp(image, approved_image, image_size))
        return X0X_MBOOT_STALE_INPUT;
    if (container_size < 0x80 || container_size > 0x3830 ||
        approved_container_size != container_size ||
        memcmp(container, approved_container, container_size) ||
        memcmp(container + 0x50, "AC79BLIDsmk37\0\0\0", 16) ||
        !terminated_version(container + 0x60))
        return X0X_MBOOT_CONTAINER;
    /* Validate actual retained TLVs, not the generated SDK [FELUCCA] stub.
     * The frozen upstream parser owns supported clock/SPI/reset semantics. */
    for (unsigned offset = 64; offset < 0xa0; offset += 32) {
        uint8_t raw[32];
        memcpy(raw, image + offset, sizeof raw);
        core_enc(0xffff, raw, sizeof raw);
        if (!core_record_parse(&record, raw))
            return X0X_MBOOT_LAYOUT;
        if (!memcmp(record.name, "isd_config.ini", sizeof "isd_config.ini")) {
            if (offset != 64 || ++configurations != 1 || record.length > 4096 ||
                !core_range(record.address, record.length, image_size) ||
                core_crc16(0, image + record.address, record.length) != record.data_crc ||
                !core_config_parse(&config, image + record.address, record.length))
                return X0X_MBOOT_CONFIG;
        }
    }
    if (configurations != 1)
        return X0X_MBOOT_CONFIG;
    /* Future first boot owns creation of TRIMCOPY. Do not overwrite or silently
     * adopt an existing reservation. No restoration runs during preparation. */
    if (memcmp(image + 0xc1224, "trimdat", 8))
        return X0X_MBOOT_CALIBRATION;
    for (unsigned i = 0xff000; i < 0xff23c; ++i)
        if (image[i] != 0xff)
            return X0X_MBOOT_CALIBRATION;
    memcpy(head, image, sizeof head);
    if (!core_boot_install(head, container, (uint32_t)container_size, image_size))
        return X0X_MBOOT_LAYOUT;
    /* Defence in depth: only the boot record and its fixed slot may differ. */
    if (memcmp(head, image, 32) || memcmp(head + 64, image + 64, 0x60) ||
        memcmp(head + 0x38d0, image + 0x38d0, sizeof head - 0x38d0))
        return X0X_MBOOT_LAYOUT;
    memcpy(output, image, image_size);
    memcpy(output, head, sizeof head);
    return X0X_MBOOT_OK;
}

/* SPDX-License-Identifier: GPL-3.0-only */
/* Transport requests in one audio block: last Start/Continue wins, Stop stays ordered. */
#include <stdio.h>
#include "../../firmware/src/seq/sequencer.h"

static seq_t S;
static pattern_t P[NPAT];
static int checks, failures, starts, continues, stops, note_offs, bass_offs;
#define CHECK(expr) do { checks++; if (!(expr)) { failures++; \
    fprintf(stderr, "FAIL line %d: %s\n", __LINE__, #expr); } } while (0)

static int drum(void *ctx, int kit, int voice, float vel) { (void)ctx; (void)kit; (void)voice; (void)vel; return 1; }
static int bass_on(void *ctx, int part, int note, int accent, int slide, int vel)
{ (void)ctx; (void)part; (void)note; (void)accent; (void)slide; (void)vel;  return 1; }
static void bass_off(void *ctx, int part) { (void)ctx; (void)part; bass_offs++; }
static void brk(void *ctx, int st, int bar, float samples, int enabled)
{ (void)ctx; (void)st; (void)bar; (void)samples; (void)enabled; }
static void brk_stop(void *ctx) { (void)ctx; }
static void midi(void *ctx, uint8_t st, uint8_t d1, uint8_t d2)
{
    (void)ctx; (void)d1; (void)d2;
    if (st == 0xFA) starts++;
    if (st == 0xFB) continues++;
    if (st == 0xFC) stops++;
    if ((st & 0xF0u) == 0x80u) note_offs++;
}
static const seq_sink_t sink = {drum, bass_on, bass_off, brk, brk_stop, midi, 0, 0};

static void reset(void)
{
    int i;
    for (i = 0; i < NPAT; i++)
        pattern_init(&P[i], (uint32_t)i + 1u, (uint32_t)i + 2u);
    seq_init(&S, P);
    starts = continues = stops = note_offs = bass_offs = 0;
}
static void consume(void) { seq_advance(&S, 0, &sink); }

int main(void)
{
    reset();
    seq_start(&S);
    seq_continue(&S);
    CHECK(!S.req_start && S.req_cont);             /* later Continue supersedes Start */
    consume();
    CHECK(starts == 0 && continues == 1);          /* no duplicate MIDI transport */
    CHECK(S.playing && !S.req_start && !S.req_cont);

    reset();
    seq_continue(&S);
    seq_start(&S);
    CHECK(S.req_start && !S.req_cont);             /* later Start supersedes Continue */
    consume();
    CHECK(starts == 1 && continues == 0);
    CHECK(S.playing);

    reset();
    S.playing = 1;
    S.t[TRK_DRUM].started = 1;
    S.t[TRK_DRUM].pos = 5;
    S.t[TRK_DRUM].to_next = 512u << 8;
    seq_start(&S);
    seq_continue(&S);
    consume();
    CHECK(S.t[TRK_DRUM].pos == 6);                  /* Continue preserves playback phase */
    CHECK(starts == 0 && continues == 1);

    reset();
    seq_start(&S);
    consume();
    seq_stop(&S);
    seq_start(&S);                                 /* Stop followed by Start is still sequential */
    consume();
    CHECK(starts == 2 && stops == 1 && continues == 0);
    CHECK(S.playing);

    reset();
    seq_start(&S);
    seq_stop(&S);                                  /* Stop after Start cancels it */
    consume();
    CHECK(!S.playing && starts == 0 && continues == 0);

    reset();
    seq_start(&S);
    consume();
    S.send_notes = 1;
    S.bass_out_valid[0] = 1;
    S.bass_notes_out[0] = 36;
    S.bass_out_ch[0] = 1;
    S.t[TRK_BASS0].sounding = 1;
    seq_start(&S);
    seq_continue(&S);
    consume();
    CHECK(note_offs == 1);                         /* exactly one Note Off for a held 303 */
    CHECK(bass_offs == 1 && !S.bass_out_valid[0]);
    CHECK(starts == 1 && continues == 1);

    reset();
    S.clk_src = S.clk_cur = SEQ_CLK_EXT;
    S.ext = 1;
    CHECK(seq_clk_take(&S, 0xFA, 0) == 1);
    CHECK(seq_midi_rt(&S, 0xFA) == 1);
    CHECK(seq_clk_take(&S, 0xFB, 0) == 1);
    CHECK(seq_midi_rt(&S, 0xFB) == 1);
    CHECK(!S.req_start && S.req_cont);             /* MIDI packet burst also coalesces */
    consume();
    CHECK(S.playing && starts == 0 && continues == 0 && stops == 0); /* no echo */

    reset();
    S.clk_src = S.clk_cur = SEQ_CLK_EXT;
    S.ext = 1;
    CHECK(seq_clk_take(&S, 0xFB, 1) == 1);
    CHECK(seq_midi_rt(&S, 0xFB) == 1);
    CHECK(seq_clk_take(&S, 0xFA, 1) == 1);
    CHECK(seq_midi_rt(&S, 0xFA) == 1);
    CHECK(S.req_start && !S.req_cont);
    consume();
    CHECK(S.playing && starts == 0 && continues == 0);

    reset();
    seq_continue(&S);
    seq_start(&S);
    seq_continue(&S);
    seq_start(&S);
    consume();
    CHECK(starts == 1 && continues == 0);          /* arbitrary burst, last request wins */


    /* MID-13: setting INTERNAL before the audio block applies cancels a
     * previously queued MIDI Start/Continue/Stop, not later local gestures. */
    reset();
    CHECK(seq_midi_rt(&S, 0xFA) == 1);
    S.clk_src = SEQ_CLK_INT;
    consume();
    CHECK(!S.playing && starts == 0 && !S.req_start && !S.req_rt);

    reset();
    CHECK(seq_midi_rt(&S, 0xFB) == 1);
    S.clk_src = SEQ_CLK_INT;
    consume();
    CHECK(!S.playing && continues == 0 && !S.req_cont);

    reset();
    S.playing = 1;
    CHECK(seq_midi_rt(&S, 0xFC) == 1);
    S.clk_src = SEQ_CLK_INT;
    consume();
    CHECK(S.playing && stops == 0 && !S.req_stop && !S.req_stop_rt);

    reset();
    seq_start(&S);
    S.clk_src = SEQ_CLK_INT;
    consume();
    CHECK(S.playing && starts == 1 && S.start_local);

    reset();
    seq_continue(&S);
    S.clk_src = SEQ_CLK_INT;
    consume();
    CHECK(S.playing && continues == 1 && S.start_local);

    reset();
    S.playing = 1;
    seq_stop(&S);
    S.clk_src = SEQ_CLK_INT;
    consume();
    CHECK(!S.playing && stops == 1);

    reset();
    CHECK(seq_midi_rt(&S, 0xFA) == 1);
    seq_continue(&S); /* local Continue supersedes remote Start */
    S.clk_src = SEQ_CLK_INT;
    consume();
    CHECK(S.playing && starts == 0 && continues == 1);

    reset();
    S.playing = 1;
    CHECK(seq_midi_rt(&S, 0xFC) == 1);
    seq_start(&S); /* local Start must survive canceled remote Stop */
    S.clk_src = SEQ_CLK_INT;
    consume();
    CHECK(S.playing && starts == 1 && stops == 0);

    reset();
    S.clk_src = SEQ_CLK_INT;
    consume();
    S.clk_src = SEQ_CLK_AUTO;
    consume();
    CHECK(seq_midi_rt(&S, 0xFA) == 1);
    consume();
    CHECK(S.playing); /* MIDI returns when AUTO is selected again */

    reset();
    seq_stop(&S); /* earlier local Stop superseded by remote Stop */
    CHECK(seq_midi_rt(&S, 0xFC) == 1);
    S.playing = 1;
    S.clk_src = SEQ_CLK_INT;
    consume();
    CHECK(S.playing && stops == 0);

    reset();
    CHECK(seq_midi_rt(&S, 0x80) == 0); /* Note Off is never clock traffic */

    fprintf(stderr, "transport-coalesce: %d checks, %d failures\n", checks, failures);
    return failures ? 1 : 0;
}

/* SPDX-License-Identifier: GPL-3.0-only
 * Clip colours of a velocity v from Loopy (APC40 mkII palette), for the LCD clip squares.
 * Include app/apc40_lcd565.h and app/apc40_lcd_idle.h first.
 * Idle shade: Loopy draws a clip that does not play in the darkest shade of an Akai group of 4
 * (v = 7, 11, ... 59, v % 4 == 3; the full shade is v - 2). Loopy also draws an empty slot in this
 * shade (BEHAVIOR.md LIM-03), so the lift also applies to empty slots. SMK_CLIP_IDLE_LIFT 0 turns
 * the LCD lift off (the plain Akai colour), SMK_CLIP_IDLE_PAD_LIFT 0 the pad lift (level / 2), as before
 * 2026-10-17. */
#pragma once
#include <stdint.h>

#ifndef SMK_CLIP_IDLE_LIFT
#define SMK_CLIP_IDLE_LIFT 1
#endif
#ifndef SMK_CLIP_IDLE_PAD_LIFT
#define SMK_CLIP_IDLE_PAD_LIFT 1
#endif

static inline uint8_t smk_clip_idle_shade(uint32_t v)
{
    return (uint8_t)(v >= 7u && v <= 59u && (v & 3u) == 3u);
}
/* CLP-05: the LCD colour (RGB565). Idle shade: half of the full shade (APC40_LCD_IDLE565). */
static inline uint16_t smk_clip_lcd565(uint32_t v)
{
    v &= 0x7Fu;
    return SMK_CLIP_IDLE_LIFT && smk_clip_idle_shade(v) ? APC40_LCD_IDLE565[(v - 7u) >> 2] : APC40_LCD565[v];
}
/* CLP-13: the byte that a clip pad sends for one channel of APC40_PAD_OWNER[v] (brightness 255 or 0).
 * Lit: level / 2, as in the calibration mode. Idle shade: the full level (2 x). */
static inline uint8_t smk_clip_pad_level(uint32_t level, uint32_t v, uint32_t brightness)
{
    return (uint8_t)((level * brightness) / (SMK_CLIP_IDLE_PAD_LIFT && smk_clip_idle_shade(v) ? 255u : 510u));
}

#!/usr/bin/env python3
# SPDX-License-Identifier: GPL-3.0-only
"""BF-029: exact engine-render callsite, linked production sequencer and motion.

The engine callsite is compiled verbatim, but other engine audio/DSP code is not linked.
The sink simulates the engine s_step call with production motion_step and seq helpers.
"""
import os, pathlib, re, subprocess, sys, tempfile
root=(pathlib.Path(sys.argv[1]) if len(sys.argv)>1 else pathlib.Path(__file__).resolve().parents[2]).resolve()
engine=(root/'firmware/src/app/engine.c').read_text()
render=engine.partition('void engine_render(')[2]
m=re.search(r'\bdrain\(\);(?:(?!PROF_ADD\(7, pt\);).)*PROF_ADD\(7, pt\);',render,re.S)
assert m,'cannot extract engine_render scheduler path'
callsite=m.group().replace('PROF_ADD(7, pt);','')
assert callsite.count('motion_tick(&mot, n);')==1
c=r'''
#include <stdio.h>
#include <string.h>
#include <stdint.h>
#include <stdlib.h>
#include "sequencer.h"
#include "motion.h"
static seq_t seq;
static pattern_t pats[NPAT];
static motion_t mot;
static lane_t lanes[NLANE];
static uint8_t mot_on=1, mot_playing=0;
static int fx, trace[128], nt, value, checks, errors, steps;
#define CHECK(C,NAME) do {checks++;if(!(C)){errors++;fprintf(stderr,"FAIL %s: playing=%d age=%u value=%d steps=%d nt=%d\n", NAME,seq.playing,mot.age[0],value,steps,nt);}}while(0)
static int base(void *x,int t,int v,int i) { (void)x;(void)t;(void)v;(void)i;return 0; }
static void apply(void *x,int t,int v,int i,int p) { (void)x;(void)t;(void)v;(void)i;value=p;if(nt<128)trace[nt++]=p; }
static void on_step(void *x,int t,int p) { (void)x;steps++;if(mot_on) motion_step(&mot,t,seq.ppat[t],p,seq_next_step(&seq,t,p),seq_part_len(&seq,t)); }
static void brkstop(void *x) {(void)x;}
static seq_sink_t SINK;
static void drain(void) {}
static void fxbus_set_bpm(int *a,float bpm) {(void)a;(void)bpm;}
static void block(uint32_t n) {
    CALLSITE
    uint32_t left=n;
    while(left) {
        uint32_t delta=seq_until_event(&seq,left);
        if(delta==0 || delta>left) { errors++;fprintf(stderr,"invalid until_event %u of %u\n",delta,left);break; }
        seq_advance(&seq,delta,&SINK);
        left-=delta;
    }
    if(mot_playing && !seq.playing) motion_release(&mot);
    mot_playing=seq.playing;
}
static void reset(void) {
    memset(pats,0,sizeof(pats));
    for(unsigned i=0;i<NPAT;i++)pattern_init(&pats[i],i+17u,i+39u);
    memset(&seq,0,sizeof(seq));seq_init(&seq,pats);
    seq.send_clock=0;seq.send_notes=0;
    memset(&mot,0,sizeof(mot));memset(lanes,0,sizeof(lanes));
    motion_init(&mot,lanes);mot.base=base;mot.apply=apply;
    memset(&SINK,0,sizeof(SINK));SINK.step=on_step;SINK.brk_stop=brkstop;
    int slot=motion_alloc(lanes,0,TRK_DRUM,1,0,0);
    if(slot!=0){errors++;fprintf(stderr,"failed lane alloc %d\n",slot);}
    lanes[slot].val[0]=30;lanes[slot].val[1]=100;
    value=0;nt=0;steps=0;mot_on=1;mot_playing=0;
}
static void initial_play(void) {
    seq_start(&seq);seq_advance(&seq,0,&SINK);
    if(!seq.playing) {errors++;fprintf(stderr,"initial start failed\n");}
    // Trigger real initial step through sequencer without advancing real audio block.
    seq_advance(&seq,0,&SINK);
    // Active interval prepared after actual events for deterministic interpolation stress.
    motion_step(&mot,TRK_DRUM,0,0,1,16);
    mot.len[TRK_DRUM][0]=100;
    mot.age[TRK_DRUM]=0;
    mot_playing=1;
}
static int has(int n) {for(int i=0;i<nt;i++)if(trace[i]==n)return 1;return 0;}
int main(void){
    reset();initial_play();seq_stop(&seq);block(50);
    CHECK(!has(65),"queued STOP must not emit transient 65 ramp");
    CHECK(!seq.playing,"queued STOP must stop");
    CHECK(mot.age[0]==0 && value==0,"queued STOP must release base");
    reset();seq_start(&seq);block(50);
    CHECK(seq.playing,"queued START must start");
    CHECK(mot.age[0]==50,"queued START counts first running block");
    CHECK(mot.len[0][0]==0,"queued START has no previous step length");
    reset();initial_play();block(50);
    CHECK(mot.age[0]==50 && value==65,"regular active motion ramps");
    reset();block(1000);
    CHECK(!seq.playing && mot.age[0]==0,"idle transport freezes age");
    reset();initial_play();seq_stop(&seq);seq_start(&seq);block(50);
    CHECK(seq.playing && mot.age[0]==50,"queued STOP then START counts block");
    reset();seq_continue(&seq);block(50);
    CHECK(seq.playing && mot.age[0]==50,"queued CONTINUE counts block");
    reset();initial_play();mot_on=0;block(50);
    CHECK(mot.age[0]==0,"disabled motion freezes age");
    fprintf(stderr,"BF029 REAL SEQUENCER + MOTION: %d/%d checks, %d failures\n",checks-errors,checks,errors);
    return errors?1:0;
}
'''.replace('CALLSITE',callsite)
cc=os.environ.get('CC','gcc');flags=os.environ.get('CFLAGS','-O2 -Wall -Wextra -Werror').split()
with tempfile.TemporaryDirectory(prefix='bf029-real-') as d:
    src=pathlib.Path(d)/'case.c';out=pathlib.Path(d)/'case';src.write_text(c)
    args=[cc,'-std=c11',*flags,'-I'+str(root/'firmware/src/seq'),str(src)] + [str(root/'firmware/src/seq'/s) for s in ['sequencer.c','pattern.c','tb3po.c','motion.c']] + ['-lm','-o',str(out)]
    p=subprocess.run(args,stdout=subprocess.PIPE,stderr=subprocess.STDOUT,text=True)
    if p.returncode:print('COMPILE exit',p.returncode,p.stdout);sys.exit(p.returncode)
    p=subprocess.run([str(out)],stdout=subprocess.PIPE,stderr=subprocess.STDOUT,text=True,env={**os.environ,'ASAN_OPTIONS':'detect_leaks=0:halt_on_error=1'})
    print(p.stdout,end='')
    sys.exit(p.returncode)

/* Deterministic whole-BREAK-renderer host trace: compare original checkpoint
 * renderer and repaired bounded reverse seek renderer, using exact verified
 * public Git breaks.c/h blobs. Not a target / MIDI ISR / device test. */
#define _POSIX_C_SOURCE 200809L
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>
#include <errno.h>
#include "firmware/src/dsp/breaks.h"

static uint32_t xs(uint32_t *s) {uint32_t x=*s;x^=x<<13;x^=x>>17;x^=x<<5;return *s=x;}
static int32_t errors;
static uint64_t frames, nonzero, zeroafter, clipped;
static uint64_t h=UINT64_C(14695981039346656037);
static void consume(const float *buf, unsigned n, FILE *out, int tail) {
  for (unsigned i=0;i<n;i++) {
    float v=buf[i];
    if (!isfinite(v) || fabsf(v)>32769.0f) {if(errors++<3)fprintf(stderr,"BAD_SAMPLE frame=%llu value=%f\n",(unsigned long long)frames,v);}
    if (v!=0.0f) nonzero++;
    if (tail && v==0.0f) zeroafter++;
    if (fabsf(v)>32767.0f) clipped++;
    uint32_t bits;memcpy(&bits,&v,4);
    for(int j=0;j<4;j++){h^=(uint8_t)(bits>>(8*j));h*=UINT64_C(1099511628211);}
    if (out && fwrite(&bits,4,1,out)!=1) {perror("write");exit(3);}
    frames++;
  }
}
static void rendern(breaks_t *b,int chunks,FILE *out,int tail){float samples[256];for(int i=0;i<chunks;i++){breaks_render(b,samples,256);consume(samples,256,out,tail);}}
static int one(uint32_t n, int mode, FILE *out){
 uint32_t n2=n-3u>=64u?n-3u:n+3u;
 size_t sz=(n+1u)/2u, sz2=(n2+1u)/2u;
 uint8_t *adpcm=malloc(sz),*adpcm2=malloc(sz2);
 breaks_t *b=calloc(1,sizeof(*b));
 if(!adpcm||!adpcm2||!b){fprintf(stderr,"ALLOC_FAIL n=%u\n",n);exit(3);}
 uint32_t seed=0x517b0d3fU+n;
 for(size_t i=0;i<sz;i++) adpcm[i]=(uint8_t)xs(&seed);
 for(size_t i=0;i<sz2;i++) adpcm2[i]=(uint8_t)xs(&seed);
 brk_loop_t a={.adpcm=adpcm,.nsamples=n,.rate=44100,.bars=1};
 brk_loop_t alt={.adpcm=adpcm2,.nsamples=n2,.rate=22050,.bars=2};
 breaks_init(b);breaks_set_loop(b,0,&a);breaks_set_loop(b,1,&alt);
 if(!b->bank[0].valid||!b->bank[1].valid||b->bank[0].n!=n) {fprintf(stderr,"BAD_BANK n=%u\n",n);return 1;}
 breaks_set(b,BRK_COMPLEX,0);
 breaks_set(b,BRK_ROLL,0);
 breaks_set(b,BRK_BCHANCE,0);
 breaks_set(b,BRK_LEVEL,111);
 for(int step=0;step<64;step++){
   if(step==4)breaks_live(b,8,1);
   if(step==12)breaks_live(b,8,0);
   if(step==16)breaks_live(b,0,1);
   if(step==20)breaks_live(b,0,0); /* physical key-release proxy, not MIDI NoteOff transport */
   if(step==24){breaks_live(b,8,1);breaks_live(b,2,1);}
   if(step==26)breaks_live(b,2,0);
   if(step==32){breaks_live(b,8,0);breaks_live(b,10,1);}
   if(step==40)breaks_live(b,10,0);
   if(step==48){breaks_set_loop(b,0,&a);breaks_live(b,8,1);} /* bank generation invalidate */
   if(step==50)breaks_live(b,8,0);
   if(step==52){breaks_set_quiet(b,1);}
   if(step==54)breaks_set_quiet(b,0);
   breaks_step(b,step%16,step/16,5512.5f,(step%7)!=5);
   rendern(b,22,out,0);
 }
 breaks_stop(b);
 breaks_live(b,8,0);
 breaks_live(b,0,0);
 breaks_live(b,2,0);
 breaks_live(b,10,0);
 rendern(b,4,out,1);
 breaks_set_quiet(b,1);
 rendern(b,2,out,1);
 printf("n=%u mode=%d frames=%llu hash=%016llx nonzero=%llu zeros_tail=%llu clipped=%llu err=%d\n",n,mode,(unsigned long long)frames,(unsigned long long)h,(unsigned long long)nonzero,(unsigned long long)zeroafter,(unsigned long long)clipped,errors);
 free(b);free(adpcm2);free(adpcm);return errors?1:0;
}
int main(int argc,char**argv){
 if(argc!=3 || strcmp(argv[1],"--trace")) {fputs("usage: --trace <filename>\n",stderr);return 2;}
 FILE *fp=fopen(argv[2],"wb");if(!fp){perror(argv[2]);return 3;}
 const uint32_t sizes[]={64,65,511,512,513,1023,1024,1025,122880,176400,705600,1411200,2116800};
 int ret=0;for(unsigned i=0;i<sizeof(sizes)/sizeof(sizes[0]);i++)ret|=one(sizes[i],i,fp);
 if(fclose(fp))return 3;
 if(nonzero==0) {fprintf(stderr,"never got nonzero audio\n");return 1;}
 return ret;
}
